import pandas as pd

# Devolva um dicionário coluna -> quantos faltantes.
def faltantes_por_coluna(df):
    return df.isna().sum().to_dict()

import pandas as pd

# Devolva, por curso, a contagem e a média da nota.
def resumo_por_curso(df):
    return df.groupby("curso")["nota"].agg(["count", "mean"])

import pandas as pd

# Junte alunos e turmas pela chave id_turma, mantendo todos os alunos,
# e faça o pandas acusar se a chave da direita estiver duplicada.
def juntar(alunos, turmas):
    return alunos.merge(turmas, on="id_turma", how="left", validate="m:1")
